import React, { useState, useEffect } from 'react';

function App() {
  const [data, setData] = useState(null);

  useEffect(() => {
    console.log("Component mounted. Setting data...");
    const staticData = "This is a static pathfinding result. HAHAS";
    setData(staticData);
  }, []);

  useEffect(() => {
    console.log("Data state updated:", data);
  }, [data]);

  return (
    <div className="App">
      <h1>Pathfinding Visualizer</h1>
      <p>{data ? data : "Loading..."}</p>
    </div>
  );
}

export default App;
